 "content": "def transform(grid):
    """Copy each populated rectangular frame's interior pattern to empty frames of the same interior size."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v != 0}
    frames = []
    for color in colors:
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        r0 = min(r for r, c in cells)
        r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells)
        c1 = max(c for r, c in cells)
        if r1-r0 < 2 or c1-c0 < 2:
            continue
        if not (all(grid[r0][c] == color for c in range(c0, c1+1)) and
                all(grid[r1][c] == color for c in range(c0, c1+1)) and
                all(grid[r][c0] == color for r in range(r0, r1+1)) and
                all(grid[r][c1] == color for r in range(r0, r1+1))):
            continue
        ih, iw = r1-r0-1, c1-c0-1
        pattern = [[grid[r0+1+i][c0+1+j] == color for j in range(iw)] for i in range(ih)]
        populated = any(any(row) for row in pattern)
        frames.append((color, r0, c0, ih, iw, pattern, populated))
    donors = {}
    for color, r0, c0, ih, iw, pattern, populated in frames:
        if populated:
            donors.setdefault((ih, iw), []).append(pattern)
    for color, r0, c0, ih, iw, pattern, populated in frames:
        if populated or (ih, iw) not in donors:
            continue
        source = donors[(ih, iw)][0]
        for i in range(ih):
            for j in range(iw):
                if source[i][j]:
                    out[r0+1+i][c0+1+j] = color
    return out
